    "price.pro_section_desc": "Pro is about working smarter, faster, and with more control over your output.",
    "price.pro_section_title": "What Pro actually feels like",
    "price.currency": "Currency",
    "price.addons": "Add-ons",
    "price.faq_heading": "FAQ",
    "price.faq_q1": "How does VOLYNX pricing work?",
    "price.faq_a1": "Plans unlock access to product features. VX is separate premium capacity for enabled actions, not a replacement for Stripe checkout. Bundles save money when you use more than one product.",
    "price.faq_q2": "What is VX?",
    "price.faq_a2": "VX is your premium usage capacity inside VOLYNX. Buy once, use where the product explicitly supports VX, such as CVitae exports/templates and selected Studio actions. VX never expires.",
    "price.faq_q3": "Can I use VX across different products?",
    "price.faq_a3": "Yes, where VX is enabled. Not every product accepts VX at checkout; product purchases still use Stripe unless the page says otherwise.",
    "price.faq_q4": "Do I need a subscription to export from CVitae?",
    "price.faq_a4": "No. CVitae is free to build, preview, and improve with AI. Use 2 VX for a clean PDF export or unlock premium templates with VX. Business is optional for professionals who need unlimited exports and templates.",
    "price.faq_q5": "How do bundles work?",
    "price.faq_a5": "Bundles combine two or more VOLYNX products into a single subscription at a combined lower price. Access updates automatically across all included products.",
    "price.faq_q6": "What's the difference between a plan and a VX pack?",
    "price.faq_a6": "A plan is a recurring subscription that unlocks ongoing access. A VX pack is a one-time purchase that adds premium usage capacity. Use them separately or together.",
    "price.faq_q7": "Can I change or cancel my plan anytime?",
    "price.faq_a7": "Yes. Upgrade, downgrade or cancel from your account dashboard. Billing adjusts automatically.",
    "price.faq_q8": "Can I buy extra VX without changing my plan?",
    "price.faq_a8": "Yes. VX packs are always available and add capacity to your account without touching your subscription.",

