    "price.faq_heading": "FAQ",
    "price.faq_q1": "Como funciona o preço da VOLYNX?",
    "price.faq_a1": "Planos liberam acesso a recursos dos produtos. VX é capacidade premium separada para ações habilitadas, não substitui checkout Stripe. Bundles economizam quando você usa mais de um produto.",
    "price.faq_q2": "O que é VX?",
    "price.faq_a2": "VX é sua capacidade premium de uso dentro da VOLYNX. Compre uma vez, use onde o produto informa suporte explícito, como exports/templates do CVitae e ações Studio selecionadas. VX não expira.",
    "price.faq_q3": "Posso usar VX entre produtos diferentes?",
    "price.faq_a3": "Sim, onde VX está habilitado. Nem todo produto aceita VX no checkout; compras de produto continuam no Stripe quando a página não disser o contrário.",
    "price.faq_q4": "Preciso de assinatura para exportar do CVitae?",
    "price.faq_a4": "Não. CVitae é grátis para criar, visualizar e melhorar com IA. Use 2 VX para exportar um PDF limpo ou liberar templates premium com VX. Business é opcional para quem precisa de exports e templates ilimitados.",
    "price.faq_q5": "Como funcionam os bundles?",
    "price.faq_a5": "Bundles combinam dois ou mais produtos da VOLYNX em uma assinatura só, com preço combinado menor. O acesso se atualiza automaticamente em todos os produtos incluídos.",
    "price.faq_q6": "Qual a diferença entre um plano e um pack de VX?",
    "price.faq_a6": "Um plano é uma assinatura recorrente que libera acesso contínuo. Um pack de VX é compra única que adiciona capacidade premium de uso. Você pode usar separadamente ou em conjunto.",
    "price.faq_q7": "Posso alterar ou cancelar meu plano quando quiser?",
    "price.faq_a7": "Sim. Upgrade, downgrade ou cancelamento direto pelo painel da conta. A cobrança se ajusta automaticamente.",
    "price.faq_q8": "Posso comprar VX extra sem mudar meu plano?",
    "price.faq_a8": "Sim. Packs de VX estão sempre disponíveis e adicionam capacidade à sua conta sem alterar sua assinatura.",

