    "discl.intro": "Este site e os materiais da Volynx são fornecidos para fins informativos e educacionais. Você é responsável por como aplica qualquer informação, ferramenta ou recomendação.",
    "discl.results_title": "Sem resultados garantidos",
    "discl.results_desc": "Quaisquer exemplos de resultados (crescimento, receita, desempenho, produtividade) são apenas ilustrativos. Os resultados variam com base em muitos fatores, incluindo experiência, esforço, condições de mercado e qualidade de implementação. Não garantimos resultados específicos.",
